package io.github.jesterportfolio.hearth.persistence;
import java.util.*;import java.util.concurrent.*;import java.sql.*;import javax.sql.DataSource;
import io.github.jesterportfolio.hearth.economy.*;
public final class PlatformOperationsDatabaseChecks {
 static <T>T await(CompletionStage<T> s)throws Exception{return s.toCompletableFuture().get(15,TimeUnit.SECONDS);}
 static void check(boolean b,String name){if(!b)throw new IllegalStateException(name);System.out.println("HEARTH_OPERATIONS_DB_CHECK PASS "+name);System.out.flush();}
 static void reject(CompletionStage<?> s)throws Exception{try{await(s);throw new IllegalStateException("EXPECTED_REJECTION");}catch(ExecutionException expected){}}
 public static void run(DataSource source,Connection c)throws Exception{
  var props=new Properties();try(var in=PlatformOperationsDatabaseChecks.class.getResourceAsStream("/economy-demo.properties")){props.load(in);}props.setProperty("fixture-balance","0");var db=PostgresProgressStore.forModules(source,f->{});var economy=new EconomyStore(db,EconomyContent.parse(props));await(economy.migrate());await(economy.migrate());UUID realm=UUID.randomUUID(),foreign=UUID.randomUUID();await(economy.openNativeRealm(realm,UUID.randomUUID(),"a".repeat(64),1,true));await(economy.openNativeRealm(foreign,UUID.randomUUID(),"b".repeat(64),1,true));var p=new PlatformStore(db,economy,realm);var a=new PlatformArchiveStore(db,economy,realm);var other=new PlatformArchiveStore(db,economy,foreign);var jobs=new JobStore(db,economy,realm);var ctx=economy.context(realm,new UUID(0,0));UUID id=UUID.randomUUID();String before="a".repeat(64),after="b".repeat(64);
  await(p.prepareConfig(id,"platform.properties",before,after));reject(a.config(await(a.config(id))));await(p.config(id,"platform.properties",before,after,"PREPARED","COMMITTED"));var original=await(a.config(id));var left=a.config(original);var right=a.config(original);int wins=0;for(var work:List.of(left,right))try{await(work);wins++;}catch(ExecutionException expected){}check(wins==1,"config_archive_CAS_one_winner_and_pending_refused");
  check(await(p.configs()).isEmpty()&&await(a.history("config",0)).size()==1&&await(a.config(id)).archived(),"archived_config_leaves_hot_set_and_keeps_original_record");reject(p.prepareConfig(id,"platform.properties",before,after));check(true,"archived_configuration_ID_cannot_be_reused");reject(other.config(id));check(await(other.history("config",0)).isEmpty(),"archive_query_is_realm_isolated");
  var job=await(jobs.reserve(ctx,UUID.randomUUID(),"fixture","novice",Map.of("seed","1"),1,null)).job();reject(a.job(job));var done=await(jobs.finish(job,JobStore.State.SUCCEEDED,"DONE",2));await(a.job(done));check(await(jobs.snapshot()).jobs().isEmpty()&&await(jobs.inspect(done.id())).orElseThrow().equals(done),"job_archive_keeps_exact_terminal_receipt_and_hides_hot_history");var replay=await(jobs.reserve(ctx,done.id(),"fixture","novice",Map.of("seed","1"),1,null));check(replay.replay()&&replay.job().equals(done),"archived_job_replay_does_not_run_effect_again");
  UUID fail=UUID.randomUUID();await(p.prepareConfig(fail,"platform.properties",before,after));await(p.config(fail,"platform.properties",before,after,"PREPARED","ROLLED_BACK"));try(var s=c.createStatement()){s.execute("CREATE FUNCTION hearth_economy.reject_archive_fixture() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'fixture' USING ERRCODE='23514'; END $$");s.execute("CREATE TRIGGER reject_archive_fixture BEFORE UPDATE ON hearth_economy.platform_config_change FOR EACH ROW EXECUTE FUNCTION hearth_economy.reject_archive_fixture()");}reject(a.config(await(a.config(fail))));check(!await(a.config(fail)).archived(),"archive_SQL_failure_preserves_hot_record");try(var s=c.createStatement()){s.execute("DROP TRIGGER reject_archive_fixture ON hearth_economy.platform_config_change");s.execute("DROP FUNCTION hearth_economy.reject_archive_fixture()");}
  // 4096 cold receipts do not exhaust the bounded active history.
  try(var s=c.prepareStatement("INSERT INTO hearth_economy.platform_config_change(realm_id,request_id,name,before_hash,after_hash,state,archived) SELECT ?,md5(i::text)::uuid,'platform.properties',?,?,'COMMITTED',true FROM generate_series(1,4096) i")){s.setObject(1,realm);s.setString(2,before);s.setString(3,after);s.executeUpdate();}UUID next=UUID.randomUUID();await(p.prepareConfig(next,"platform.properties",before,after));check(await(p.configs()).size()==2&&await(a.history("config",0)).size()==36,"cold_history_over_4096_does_not_consume_hot_capacity");await(p.config(next,"platform.properties",before,after,"PREPARED","COMMITTED"));
  UUID base=UUID.randomUUID();var first=await(p.reserve(UUID.randomUUID(),"novice",base,0,1,"FLAT"));var ready=await(p.prepared(first,UUID.randomUUID(),0,64,0));await(p.activate(ready));reject(a.prepare(ready,"c".repeat(64)));check(true,"active_world_cannot_be_archived");var second=await(p.reserve(UUID.randomUUID(),"novice",ready.world(),1,2,"FLAT"));var r2=await(p.prepared(second,UUID.randomUUID(),0,64,0));await(p.activate(r2));var third=await(p.reserve(UUID.randomUUID(),"novice",r2.world(),2,3,"FLAT"));var r3=await(p.prepared(third,UUID.randomUUID(),0,64,0));await(p.activate(r3));var retired=await(p.reset(first.request()));var vault=await(a.prepare(retired,"c".repeat(64)));var l=a.transition(vault,"STORED");var r=a.transition(vault,"STORED");wins=0;for(var work:List.of(l,r))try{await(work);wins++;}catch(ExecutionException expected){}check(wins==1&&await(p.resets()).stream().noneMatch(v->v.request().equals(first.request())),"world_archive_CAS_one_winner_and_cold_generation_leaves_hot_set");
  var stored=await(a.vault(first.request())).orElseThrow();var restoring=await(a.transition(stored,"RESTORING"));var restored=await(a.transition(restoring,"RESTORED"));check(restored.revision()==3&&await(p.reset(first.request())).world().equals(ready.world()),"world_restore_journal_preserves_original_world_identity");
  long start=System.nanoTime();var times=new ArrayList<Long>();for(int batch=0;batch<16;batch++){var tasks=new ArrayList<CompletionStage<?>>();for(int i=0;i<8;i++){long at=System.nanoTime();tasks.add(a.history("config",i*36).thenAccept(v->{synchronized(times){times.add(System.nanoTime()-at);}}));}for(var task:tasks)await(task);}Collections.sort(times);System.out.println("HEARTH_OPERATIONS_LOAD queries=128 elapsed_ms="+(System.nanoTime()-start)/1_000_000+" p95_us="+times.get(121)/1000+" max_us="+times.getLast()/1000);check(times.size()==128,"bounded_concurrent_cold_history_reads_complete_without_writes");await(db.closeAsync());
 }
}
